mapper.select:
SELECT oiad.main_id, SUM(CASE WHEN oiad.inventory_age BETWEEN 0 AND 30 THEN oiad.inventory_qty ELSE 0 END) AS inventoryAge0To30Days, SUM(CASE WHEN oiad.inventory_age BETWEEN 31 AND 60 THEN oiad.inventory_qty ELSE 0 END) AS inventoryAge31To60Days, SUM(CASE WHEN oiad.inventory_age BETWEEN 61 AND 90 THEN oiad.inventory_qty ELSE 0 END) AS inventoryAge61To90Days, SUM(CASE WHEN oiad.inventory_age BETWEEN 91 AND 180 THEN oiad.inventory_qty ELSE 0 END) AS inventoryAge91To180Days, SUM(CASE WHEN oiad.inventory_age BETWEEN 181 AND 270 THEN oiad.inventory_qty ELSE 0 END) AS inventoryAge181To270Days, SUM(CASE WHEN oiad.inventory_age BETWEEN 271 AND 365 THEN oiad.inventory_qty ELSE 0 END) AS inventoryAge271To365Days, SUM(CASE WHEN oiad.inventory_age > 365 THEN oiad.inventory_qty ELSE 0 END) AS inventoryAge365PlusDays FROM overseas_inventory_age_detail oiad WHERE oiad.is_deleted = FALSE AND oiad.pull_date = #{nowDate}
AND oiad.main_id in
#{item}
GROUP BY oiad.main_id;
